// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }
    function testFuzz_property(uint256 burnAmount, uint256 mintAmount, address target) public {
        vm.assume(target != address(0));
        vm.assume(address(this) != target);
        vm.assume(burnAmount <= type(uint256).max);
        vm.assume(mintAmount <= type(uint256).max - 10**18);

        // Setup: mint to target
        c.mintToken(target, mintAmount);

        // Record balances before burn
        uint256 ownerBefore = c.balanceOf(address(this));

        // Ensure owner has enough balance to burn
        vm.assume(burnAmount <= ownerBefore);

        // Perform burn
        c.burn(burnAmount);

        // Owner balance should be original minus burn amount
        assertTrue(c.balanceOf(address(this)) == ownerBefore - burnAmount);
    }
}

